cat inputs/inputs/brief.txt; python - <<'PY'
from pathlib import Path
import zipfile, xml.etree.ElementTree as E
for p in sorted(Path('inputs/inputs/baselines/audiveris-enlarged').glob('*')):
 print('\nSOURCE',p)
 if p.suffix=='.krn': print(p.read_text())
 else:
  if p.suffix=='.mxl':
   with zipfile.ZipFile(p) as z:
    names=[n for n in z.namelist() if n.endswith('.xml') and not n.startswith('META-INF')]
    root=E.fromstring(z.read(names[0]))
  else: root=E.parse(p).getroot()
  print('parts',len(root.findall('part')),'notes',len(root.findall('.//note')),'harmonies',len(root.findall('.//harmony')))
  for part in root.findall('part'):
   for m in part.findall('measure'):
    hs=m.findall('harmony')
    if hs: print('measure',m.get('number'),[E.tostring(h,encoding='unicode') for h in hs])
PY
